import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { inventoryAPI, upgradesAPI, dashboardAPI, authAPI } from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';

const UpgradePage = () => {
  const { balance: authBalance } = useAuth();
  const [inventory, setInventory] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [selectedItemId, setSelectedItemId] = useState(null);
  const [selectedTargetItemId, setSelectedTargetItemId] = useState(null);
  const [upgradeResult, setUpgradeResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [allItemsLoading, setAllItemsLoading] = useState(true);
  const [balance, setBalance] = useState(0);

  useEffect(() => {
    const fetchInventory = async () => {
      try {
        const inventoryResponse = await inventoryAPI.getInventory();
        setInventory(inventoryResponse.data);
      } catch (error) {
        console.error('Error fetching inventory:', error);
      } finally {
        setLoading(false);
      }
    };

    const fetchAllItems = async () => {
      try {
        const allItemsResponse = await api.get('/items/');
        setAllItems(allItemsResponse.data);
      } catch (error) {
        console.error('Error fetching all items:', error);
      } finally {
        setAllItemsLoading(false);
      }
    };

    const fetchBalance = async () => {
      try {
        const { data } = await authAPI.getCurrentUser();
        setBalance(data.virtual_balance);
      } catch (error) {
        console.error('Error fetching balance:', error);
      }
    };

    fetchInventory();
    fetchAllItems();
    fetchBalance();
  }, []);

  const handleItemSelect = (itemId) => {
    setSelectedItemId(prev => prev === itemId ? null : itemId);
  };

  const handleUpgrade = async () => {
    if (!selectedItemId) {
      alert('Please select an item to upgrade');
      return;
    }
    if (!selectedTargetItemId) {
      alert('Please select a target item');
      return;
    }

    const originalItemId = selectedItemId;
    const targetItemId = selectedTargetItemId;

    // Find original item object to get its value for validation
    const originalItem = inventory.find(item => item.item_id === originalItemId)?.item;
    const targetItem = allItems.find(item => item.id === targetItemId);

    if (!originalItem || !targetItem) {
      alert('Invalid item selection');
      return;
    }

    if (targetItem.virtual_value <= originalItem.virtual_value) {
      alert('Target item must be more valuable than original item');
      return;
    }

    try {
      const response = await upgradesAPI.performUpgrade({
        original_item_id: originalItemId,
        target_item_id: targetItemId
      });
      // Upgrade successful or not, we still got a record
      setUpgradeResult(response.data);
      // Refresh inventory and balance after upgrade
      const freshInventory = await inventoryAPI.getInventory();
      setInventory(freshInventory.data);
      const freshBalance = await dashboardAPI.getBalance();
      setBalance(freshBalance.data.balance);
    } catch (error) {
      console.error('Error performing upgrade:', error);
      alert('Error performing upgrade: ' + (error.response?.data?.detail || error.message || 'Request failed'));
    }
  };

  if (loading || allItemsLoading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">Upgrade</h1>
      <div className="alert alert-info">
        Virtual currency — no real-money value
      </div>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>

      {/* Upgrade Instructions */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="card">
            <div className="card-body">
              <h5>How to Upgrade</h5>
              <p>Select 1 item from your inventory to upgrade, and select a target item that is more valuable.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Inventory Selection (Original Item) */}
      <div className="row mb-4">
        <div className="col-12">
          <h5>Select Item to Upgrade ({selectedItemId ? '1 selected' : '0 selected'})</h5>
          <div className="row g-3">
            {inventory.length > 0 ? (
              inventory.map(item => (
                <div key={item.id} className="col-md-3 col-sm-6">
                  <div className="card hover-lift position-relative">
                    <div className="card-body text-center p-3">
                      <div className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-selection">
                        {selectedItemId === item.item_id && '✓'}
                      </div>
                      <ImageWithFallback
                           src={item.item?.image_url}
                           alt={item.item?.name || 'Unknown Item'}
                           className="item-image img-fluid mb-3"
                           style={{ maxWidth: '60px', maxHeight: '60px' }}
                      />
                      <h6 className="card-title">{item.item?.name || 'Unknown Item'}</h6>
                      <p className="text-muted small mb-2">{item.item?.category || ''}</p>
                      <div className="mb-2">
                        <span className={`badge bg-${item.item?.rarity?.toLowerCase() || 'secondary'} fs-6 px-2 py-1`}>
                          {item.item?.rarity || 'Common'}
                        </span>
                      </div>

                      <button className="btn btn-outline-primary w-100 btn-sm"
                              onClick={() => handleItemSelect(item.item_id)}>
                        {selectedItemId === item.item_id ? 'Deselect' : 'Select'}
                      </button>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="col-12">
                <div className="text-center py-4">
                  <p className="text-muted">No items in inventory</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Target Item Selection */}
      <div className="row mb-4">
        <div className="col-12">
          <h5>Select Target Item</h5>

          {allItems.length > 0 ? (
            <div className="row g-3">
              {allItems.map(item => (
                <div key={item.id} className="col-md-3 col-sm-6">
                  <div className="card hover-lift position-relative">
                    <div className="card-body text-center p-3">

                      <div className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-selection">
                        {selectedTargetItemId === item.id && '✓'}
                      </div>

                      <ImageWithFallback
                        src={item.image_url}
                        alt={item.name || 'Unknown Item'}
                        className="item-image img-fluid mb-3"
                        style={{ maxWidth: '60px', maxHeight: '60px' }}
                      />

                      <h6 className="card-title">{item.name || 'Unknown Item'}</h6>

                      <p className="text-muted small mb-2">
                        {item.category || ''}
                      </p>

                      <div className="mb-2">
                        <span className={`badge bg-${item.rarity?.toLowerCase() || 'secondary'} fs-6 px-2 py-1`}>
                          {item.rarity || 'Common'}
                        </span>
                      </div>

                      <button
                        className="btn btn-outline-primary w-100 btn-sm"
                        onClick={() => setSelectedTargetItemId(item.id)}
                      >
                        {selectedTargetItemId === item.id ? 'Selected' : 'Select'}
                      </button>

                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="col-12">
              <div className="text-center py-4">
                <p className="text-muted">No items available</p>
              </div>
            </div>
          )}

        </div>
      </div>
      {/* Upgrade Button */}
      <div className="row mb-4">
        <div className="col-12">
          <button className="btn btn-primary w-100 pw-btn"
                  onClick={handleUpgrade}
                  disabled={!selectedItemId || !selectedTargetItemId || !!upgradeResult}>
            {upgradeResult ? 'Processing...' : 'UPGRADE'}
          </button>
        </div>
      </div>

      {/* Upgrade Result */}
      {upgradeResult && (
        <div className="row">
          <div className="col-12">
            <div className="card text-center py-4">
              {upgradeResult.was_successful ? (
                <>
                  <div className="mb-3">
                    <i className="bi bi-star-fill display-1 text-warning"></i>
                  </div>
                  <h4>Upgrade Successful!</h4>
                  <p className="mb-3">
                    You upgraded <strong>{inventory.find(i => i.item_id === upgradeResult.original_item_id)?.item?.name || 'Original Item'}</strong>
                    to <strong>{upgradeResult.target_item_id ? allItems.find(i => i.id === upgradeResult.target_item_id)?.name || 'Target Item' : 'Unknown'}</strong>.
                  </p>
                  <p className="mb-2">
                    Success Chance: {upgradeResult.success_chance?.toFixed(2)}%
                  </p>
                  <p className="mb-2">
                    Balance: €{upgradeResult.virtual_balance_before.toLocaleString()} → €{upgradeResult.virtual_balance_after.toLocaleString()}
                  </p>
                  <button className="btn btn-outline-primary w-100"
                          onClick={() => setUpgradeResult(null)}>
                    Continue
                  </button>
                </>
              ) : (
                <>
                  <div className="mb-3">
                    <i className="bi bi-x-octagon display-1 text-danger"></i>
                  </div>
                  <h4>Upgrade Failed</h4>
                  <p className="mb-3">
                    You lost <strong>{inventory.find(i => i.item_id === upgradeResult.original_item_id)?.item?.name || 'Original Item'}</strong>.
                  </p>
                  <p className="mb-2">
                    Success Chance: {upgradeResult.success_chance?.toFixed(2)}%
                  </p>
                  <p className="mb-2">
                    Balance remained: €{upgradeResult.virtual_balance_before.toLocaleString()}
                  </p>
                  <button className="btn btn-outline-primary w-100"
                          onClick={() => setUpgradeResult(null)}>
                    Try Again
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UpgradePage;
